def max_product(num_str: str, N: int, K: int) -> int:
    """
    Returns the maximum product obtainable by inserting exactly K multiplication signs
    into the digit string `num_str` (length N). Each multiplication sign splits
    the string into contiguous numeric substrings whose values are multiplied together.

    Parameters:
    - num_str: string of digits representing the number.
    - N: length of the string (should be equal to len(num_str)).
    - K: number of multiplication signs (cuts) to insert.

    Returns:
    The maximum product as an integer. If K is 0, returns the integer value of the whole string.
    If K > N - 1, returns 0.
    """
    if K < 0:
        return 0
    if N != len(num_str):
        return 0
    if K == 0:
        return int(num_str)
    if K > N - 1:
        return 0

    # dp[i][k] is the maximum product for the first i digits with k cuts
    dp = [[0] * (K + 1) for _ in range(N + 1)]

    # Base case: no cuts, the whole prefix is one number
    for i in range(1, N + 1):
        dp[i][0] = int(num_str[:i])

    for k in range(1, K + 1):
        # Need at least k+1 digits to have k cuts
        for i in range(k + 1, N + 1):
            best = 0
            # last number starts at position j, ends at i
            for j in range(k, i):
                if dp[j][k - 1] == 0:
                    continue
                cur_val = int(num_str[j:i])
                cur_prod = dp[j][k - 1] * cur_val
                if cur_prod > best:
                    best = cur_prod
            dp[i][k] = best

    return dp[N][K]

